namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Analysis of past events, societies, and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She holds a PhD from MIT and specializes in CS education research.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a former software engineer at Google who now researches algorithm optimization. PhD from Stanford.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez has extensive industry experience in distributed database systems. She previously worked at Oracle and Amazon.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to supervised and unsupervised learning, neural networks, and practical applications of ML in real-world scenarios.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Alan Wright", InstructorBio = "Dr. Wright leads the university's AI research lab and has published over 50 papers in top ML conferences.", DepartmentId = 1, DepartmentCode = "CS", DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Zhao", InstructorBio = "Dr. Zhao specializes in applied linear algebra and its connections to machine learning.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, statistical inference, and hypothesis testing.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentCode = "MATH", DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 8, Code = "ENG 101", Title = "College Writing", Description = "Develop critical reading and writing skills through analysis of diverse texts and composition of argumentative essays.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Diana Hart", InstructorBio = "Prof. Hart is a published author and writing coach who has mentored hundreds of students in academic and creative writing.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and democracy.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Marcus Reed", InstructorBio = "Dr. Reed is a specialist in 20th-century American fiction and has authored two books on the Harlem Renaissance.", DepartmentId = 3, DepartmentCode = "ENG", DepartmentName = "English", IsFeatured = true },
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Victor Patel", InstructorBio = "Dr. Patel is an experimental physicist whose research focuses on quantum optics. He brings cutting-edge science into the classroom.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 11, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I with lab component.", Credits = 4, Schedule = "Mon/Wed/Fri 2:00–2:50 PM + Tue Lab 3:00–5:00 PM", InstructorName = "Dr. Victor Patel", InstructorBio = "Dr. Patel is an experimental physicist whose research focuses on quantum optics. He brings cutting-edge science into the classroom.", DepartmentId = 4, DepartmentCode = "PHYS", DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural exchanges from prehistory through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Olivia Grant", InstructorBio = "Dr. Grant is an archaeologist and historian whose fieldwork spans sites in Mesopotamia and the Mediterranean.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = false },
            new() { Id = 13, Code = "HIST 250", Title = "Modern European History", Description = "Political, social, and cultural developments in Europe from the Enlightenment to the present day.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Thomas Novak", InstructorBio = "Dr. Novak specializes in Cold War history and has served as a visiting scholar at universities across Europe.", DepartmentId = 5, DepartmentCode = "HIST", DepartmentName = "History", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

